action_details.action_postfix:
// Physical nexus established - filing required
true result.md_has_nexus xdef
"Maryland filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.md_has_nexus xdef
"Maryland filing required: Economic nexus (exceeds $100,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Maryland state additions
0.0 /md_additions xdef

// Common Maryland additions:
// - Federal bond interest
// - IRC 199A qualified business income deduction addback
// - Bonus depreciation (MD decouples from federal)

result.md_us_interest_income 0.0 ne
{
  md_additions result.md_us_interest_income add /md_additions xdef
} if

md_additions result.md_state_additions xdef

// Calculate Maryland state subtractions
0.0 /md_subtractions xdef

// Common Maryland subtractions:
// - Maryland municipal bond interest
// - State NOL deduction
// - State income taxes paid

result.md_municipal_interest 0.0 ne
{
  md_subtractions result.md_municipal_interest add /md_subtractions xdef
} if

md_subtractions result.md_state_subtractions xdef

"Maryland additions: $" result.md_state_additions cvs strconcat ", subtractions: $" strconcat result.md_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Maryland taxable income // Federal taxable income apportioned to MD + additions - subtractions result.md_apportioned_income result.md_state_additions add result.md_state_subtractions sub 0.0 max result.md_taxable_income xdef
// Calculate Maryland tax using flat rate: 8.25% result.md_taxable_income result.md_corp_tax_rate mul /md_tax_before_credits xdef
// Subtract Maryland state credits (R&D, job creation, biotechnology, etc.) md_tax_before_credits result.md_state_credits sub 0.0 max result.md_tax_liability xdef
// Calculate refund or amount owed result.md_estimated_payments result.md_tax_liability sub result.md_refund_or_owed xdef
"Maryland taxable income: $" result.md_taxable_income cvs strconcat job.audit_trail swap addto "Maryland tax liability (8.25%): $" result.md_tax_liability cvs strconcat job.audit_trail swap addto
